// Package billing is invoice arithmetic and billing periods. It holds no state.
package billing

import (
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Totals are the amounts shown on an invoice, in the invoice currency's minor unit.
type Totals struct {
	Subtotal int64 `json:"subtotal"`
	Discount int64 `json:"discount"`
	Tax      int64 `json:"tax"`
	Total    int64 `json:"total"`
}

// Compute returns an invoice's totals: the sum of its lines, the discount (DiscountPercent of the subtotal), and tax at the
// invoice's rate on the subtotal after the discount. The discount and the tax are each rounded half away from zero to a
// whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := money.Percent(subtotal, inv.DiscountPercent)
	taxable := subtotal - discount
	tax := money.BasisPoints(taxable, inv.TaxRateBP)
	return Totals{Subtotal: subtotal, Discount: discount, Tax: tax, Total: taxable + tax}
}

// AddInterval returns t moved forward by one billing interval: a month or a year.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	if iv == store.Yearly {
		return t.AddDate(1, 0, 0)
	}
	return t.AddDate(0, 1, 0)
}
package billing

import (
	"testing"
	"time"

	"example.com/tally/internal/store"
)

func TestCompute(t *testing.T) {
	inv := store.Invoice{
		Lines:           []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}},
		DiscountPercent: 10,
		TaxRateBP:       825,
	}
	got := Compute(inv)
	// subtotal 5499; discount 549.9 -> 550; taxable 4949; tax 408.2925 -> 408
	want := Totals{Subtotal: 5499, Discount: 550, Tax: 408, Total: 5357}
	if got != want {
		t.Fatalf("Compute = %+v, want %+v", got, want)
	}
}

func TestComputeWithoutDiscountOrTax(t *testing.T) {
	got := Compute(store.Invoice{Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 250}}})
	if got != (Totals{Subtotal: 500, Total: 500}) {
		t.Fatalf("Compute = %+v", got)
	}
}

func TestAddInterval(t *testing.T) {
	start := time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)
	if got := AddInterval(start, store.Monthly); !got.Equal(time.Date(2026, 4, 14, 9, 30, 0, 0, time.UTC)) {
		t.Errorf("monthly: %v", got)
	}
	if got := AddInterval(start, store.Yearly); !got.Equal(time.Date(2027, 3, 14, 9, 30, 0, 0, time.UTC)) {
		t.Errorf("yearly: %v", got)
	}
}
