	}
}

func TestPeriodStartDoesNotDrift(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC)
	want := []time.Time{
		time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC),
