			t.Errorf("period %d starts %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartYearlyFromLeapDay(t *testing.T) {
	anchor := time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)
	for _, c := range []struct {
		n    int
		want time.Time
	}{
		{0, time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)},
		{1, time.Date(2029, 2, 28, 0, 0, 0, 0, time.UTC)},
		{2, time.Date(2030, 2, 28, 0, 0, 0, 0, time.UTC)},
		{3, time.Date(2031, 2, 28, 0, 0, 0, 0, time.UTC)},
		{4, time.Date(2032, 2, 29, 0, 0, 0, 0, time.UTC)},
