+	if got := AddInterval(feb29, store.Yearly); !got.Equal(time.Date(2029, 2, 28, 9, 30, 0, 0, time.UTC)) {
+		t.Errorf("yearly from Feb 29: %v", got)
+	}
+}
+
+func TestPeriodStartDoesNotDrift(t *testing.T) {
+	anchor := time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC)
+	want := []time.Time{
+		time.Date(2026, 1, 31, 9, 30, 0, 0, time.UTC),
+		time.Date(2026, 2, 28, 9, 30, 0, 0, time.UTC),
+		time.Date(2026, 3, 31, 9, 30, 0, 0, time.UTC),
+		time.Date(2026, 4, 30, 9, 30, 0, 0, time.UTC),
+		time.Date(2026, 5, 31, 9, 30, 0, 0, time.UTC),
+		time.Date(2026, 6, 30, 9, 30, 0, 0, time.UTC),
+	}
+	for n, w := range want {
+		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
+			t.Errorf("period %d starts %v, want %v", n, got, w)
+		}
+	}
+}
+
+func TestPeriodStartYearlyFromLeapDay(t *testing.T) {
+	anchor := time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)
+	for _, c := range []struct {
+		n    int
+		want time.Time
+	}{
+		{0, time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)},
+		{1, time.Date(2029, 2, 28, 0, 0, 0, 0, time.UTC)},
+		{2, time.Date(2030, 2, 28, 0, 0, 0, 0, time.UTC)},
+		{3, time.Date(2031, 2, 28, 0, 0, 0, 0, time.UTC)},
+		{4, time.Date(2032, 2, 29, 0, 0, 0, 0, time.UTC)},
+	} {
+		if got := PeriodStart(anchor, store.Yearly, c.n); !got.Equal(c.want) {
+			t.Errorf("period %d starts %v, want %v", c.n, got, c.want)
+		}
+	}
+}
+
+func TestPeriodsAreContiguous(t *testing.T) {
+	anchor := time.Date(2026, 8, 31, 23, 59, 59, 5, time.UTC)
+	for n := 0; n < 30; n++ {
+		end := PeriodStart(anchor, store.Monthly, n+1)
+		if got := NextPeriodEnd(anchor, store.Monthly, PeriodStart(anchor, store.Monthly, n)); !got.Equal(end) {
+			t.Errorf("period %d ends %v, want %v (the next period's start)", n, got, end)
+		}
+	}
+}
+
+func TestNextPeriodEndAfterALateRun(t *testing.T) {
+	anchor := time.Date(2026, 1, 31, 9, 0, 0, 0, time.UTC)
+	for _, c := range []struct {
+		from time.Time
+		want time.Time
+	}{
+		// The period that ended Feb 28 at 09:00 runs to Mar 31, however late the job is.
+		{time.Date(2026, 2, 28, 9, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC)},
+		{time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 9, 0, 0, 0, time.UTC)},
+		{time.Date(2026, 12, 31, 9, 0, 0, 0, time.UTC), time.Date(2027, 1, 31, 9, 0, 0, 0, time.UTC)},
+		// From a time that is not a boundary, the first boundary after it.
+		{time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 9, 0, 0, 0, time.UTC)},
+	} {
+		if got := NextPeriodEnd(anchor, store.Monthly, c.from); !got.Equal(c.want) {
+			t.Errorf("NextPeriodEnd(%v) = %v, want %v", c.from, got, c.want)
+		}
+	}
+}
+
+func TestAnchorIsTheTrialEndWhenThereIsATrial(t *testing.T) {
+	started := time.Date(2026, 1, 17, 8, 0, 0, 0, time.UTC)
+	trialEnd := time.Date(2026, 1, 31, 8, 0, 0, 0, time.UTC)
+	if got := Anchor(store.Subscription{StartedAt: started}); !got.Equal(started) {
+		t.Errorf("no trial: anchor %v, want %v", got, started)
+	}
+	if got := Anchor(store.Subscription{StartedAt: started, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
+		t.Errorf("trial: anchor %v, want %v", got, trialEnd)
+	}
+}
+
+func TestPeriodsAreInUTC(t *testing.T) {
+	// Feb 1 08:30 in Tokyo is Jan 31 23:30 UTC, so the anchor's day is Jan 31 and period 1 is Feb 28 at 23:30 UTC.
+	tokyo := time.FixedZone("JST", 9*60*60)
+	anchor := time.Date(2026, 2, 1, 8, 30, 0, 0, tokyo)
+	if got := PeriodStart(anchor, store.Monthly, 1); !got.Equal(time.Date(2026, 2, 28, 23, 30, 0, 0, time.UTC)) || got.Location() != time.UTC {
+		t.Errorf("period 1 = %v", got)
+	}
+}

